      raise ArgumentError, "unknown locker #{number.inspect}" unless number.is_a?(Integer) && @lockers.any? { |n, _| n == number }
    end

    def tick(minute)
      @now = minute if minute > @now
    end

    def active_holds
      @holds.values.select { |h| h.expires > @now }.sort_by(&:code)
