module Stowbox
  # An active rental of one locker.
  class Rental
    attr_reader :token, :locker, :size, :start
    attr_accessor :member

    def initialize(token, locker, size, start)
      @token = token
      @locker = locker
      @size = size
      @start = start
      @moves = [[start, size]]
    end

    def pin=(pin)
      @pin = pin
    end

    def pin_protected?
      !@pin.nil?
    end

    def pin_ok?(given)
      @pin.nil? || @pin == given
    end

    def moves
      @moves.map(&:dup)
    end

    def move_to(locker, size, minute)
      @locker = locker
      @size = size
      @moves << [minute, size]
    end

    # The size the rental had at a given minute (not before the start).
    def size_at(minute)
      @moves.select { |m, _| m <= minute }.last.last
    end
  end
end

