      check_size!(size)
      check_minute!(minute)
      tick(minute)
      number = free_numbers(size).first
      raise Full, "no free #{size} locker" if number.nil?

      @hold_seq += 1
      hold = Reservation.new(format("R%03d", @hold_seq), size, number, minute, minute + 60)
      @holds[hold.code] = hold
      hold
    end

