module Stowbox
  # An active rental of one locker.
  class Rental
    attr_reader :token, :locker, :size, :start
    attr_accessor :member

    def initialize(token, locker, size, start)
      @token = token
      @locker = locker
      @size = size
      @start = start
    end

    def pin=(pin)
      @pin = pin
    end

    def pin_protected?
      !@pin.nil?
    end

    def pin_ok?(given)
      @pin.nil? || @pin == given
    end
  end
end

