module Stowbox
  # A locker that is held for somebody who is on the way.
  class Reservation
    attr_reader :code, :size, :locker, :made, :expires

    def initialize(code, size, locker, made, expires)
      @code = code
      @size = size
      @locker = locker
      @made = made
      @expires = expires
    end
  end
end
